assert len(rows)==33
levels=[]
for i,(letter,mode,fixed,instruction,hint,fact,distractors,prop) in enumerate(rows):
    assert old[i]['letter']==letter
    name=old[i]['name']; spoken=name.lower()
    finish=f'Ты собрал и нашёл букву {spoken}! '+old[i]['finish']
    if letter=='Ъ':finish='Ты собрал и нашёл твёрдый знак! Сам он не звучит. Было «сел», стало «съел». Вот так фокус!'
    if letter=='Я':finish='Ты собрал и нашёл букву я! Вот это кино! Буква Я вышла на сцену, а яблоко решило стать режиссёром!'
    if letter=='Ь':finish='Ты собрал и нашёл мягкий знак! У него нет своего звука. А герой уснул на его мягком животике!'
    find=f'Получилась буква {spoken}! {fact} А теперь найди её среди других букв.'
    if letter in ['Ъ','Ь']:find=f'Получился {spoken}! {fact} А теперь найди его среди других букв.'
    levels.append({**old[i],'mode':mode,'fixed':fixed,'instruction':instruction,'hint':hint,
        'fact':fact,'find':find,'findDisplay':find.replace(f'буква {spoken}!',f'буква {letter}!',1),'finishDisplay':finish.replace(f'букву {spoken}!',f'букву {letter}!',1),'findHint':f'{fact} Сравни с маленьким образцом и найди {spoken}.',
        'finish':finish,'distractors':distractors,'prop':prop})
(ROOT/'docs/data.js').write_text('// Letter-centred stories: building the printed form and recognising it are required.\nexport const LEVELS = '+json.dumps(levels,ensure_ascii=False,indent=2)+';\n')
names={x['letter']:x['name'].lower() for x in levels}
import re
def spoken(text):
    text=re.sub(r'(букв[ауыое]\s+)([А-ЯЁ])(?=[\s.,!?:])',lambda m:m[1]+names[m[2]],text)
    for before,after in {'Получилась Г!':'Получилась буква гэ!','Была И, получилась Й!':'Была буква и, получилась буква и краткое!','Пуговичная П готова!':'Пуговичная буква пэ готова!','Сырная Ы готова!':'Сырная буква ы готова!'}.items():text=text.replace(before,after)
    return text
jobs=[]
for i,l in enumerate(levels):
    name=f"Это буква {l['name'].lower()}. {l['fact']}"
    if l['letter'] in ['Ъ','Ь']:name=f"Это {l['name'].lower()}. У него нет своего звука. {l['fact']}"
    for kind,text,tag in [('intro',l['instruction'],'[curious]'),('hint',l['hint'],'[warmly]'),
        ('find',l['find'],'[excited]'),('find-hint',l['findHint'],'[warmly]'),
        ('finish',l['finish'],'[delighted]'),('name',name,'[warmly]')]:
        performance=tag+' '+spoken(text)
        if kind=='finish':performance=performance.replace('! ','! [amused] ',1)
        jobs.append({'file':f'{i}-{kind}.m4a','text':text,'performed_text':performance})
    for j,w in enumerate(l['words']):jobs.append({'file':f'{i}-word-{j}.m4a','text':w+'.','performed_text':'[warmly] '+w.capitalize()+'.'})
jobs.extend([
 {'file':'welcome.m4a','text':'Привет! Я Бум. А это Шмяк! Будем собирать буквы, узнавать их и хихикать. Выбирай любую букву!','performed_text':'[mischievously] Приве-е-ет! Я Бум. А это Шмяк! [curious] Будем собирать буквы, узнавать их и хихикать. [warmly] Выбирай любую букву!'},
 {'file':'collection.m4a','text':'Это твои буквы! Ты собрал их и узнал среди других. Можно поиграть с ними снова!','performed_text':'[delighted] Это твои буквы! Ты собрал их и узнал среди других. [warmly] Можно поиграть с ними снова!'},
 {'file':'find-again.m4a','text':'Точно! А теперь найди эту букву ещё раз. Она поменялась местами!','performed_text':'[delighted] Точно! [mischievously] А теперь найди эту букву ещё раз. Она поменялась местами!'},
])
assert len(jobs)==300 and len({j['file'] for j in jobs})==300
manifest={'provider':'ElevenLabs','model':'eleven_v4','voice':'Denis','voice_id':'0BcDz9UPwL3MpsnTeUlO',
 'format':'AAC mono, 44.1 kHz, 80 kbit/s','count':len(jobs),'status':'scripts_final','files':jobs}
(ROOT/'denis-narration-plan.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
print(f"Authored 33 letter-centred scenarios, {len(jobs)} clips, {sum(len(j['performed_text']) for j in jobs)} characters.")
